public void selectDate(String day, String month, String year) {
    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

    driver.findElement(By.id("departure-date")).click();

    By header = By.cssSelector(".datepicker .month-year");
    By next = By.cssSelector(".datepicker .next");
    String target = month + " " + year;

    int guard = 0;
    while (!wait.until(ExpectedConditions.visibilityOfElementLocated(header))
                .getText().trim().equals(target)) {
        driver.findElement(next).click();
        if (++guard > 36) {
            throw new IllegalStateException("Month not found: " + target);
        }
    }

    By dayCell = By.xpath("//div[contains(@class,'datepicker')]"
            + "//td[not(contains(@class,'disabled')) and normalize-space()='" + day + "']");
    wait.until(ExpectedConditions.elementToBeClickable(dayCell)).click();
}

