import java.net.HttpURLConnection;
import java.net.URL;
import java.util.LinkedHashSet;
import java.util.Set;
import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;

public class BrokenLinks {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        try {
            driver.get("https://the-internet.herokuapp.com/");

            Set<String> urls = new LinkedHashSet<>();
            for (WebElement link : driver.findElements(By.tagName("a"))) {
                String href = link.getAttribute("href");
                if (href != null && href.startsWith("http")) {
                    urls.add(href);
                }
            }
            System.out.println("Unique links: " + urls.size());

            int broken = 0;
            for (String url : urls) {
                int code = getStatus(url);
                if (code >= 400 || code == -1) {
                    broken++;
                    System.out.println("BROKEN  " + code + "  " + url);
                } else {
                    System.out.println("OK      " + code + "  " + url);
                }
            }
            System.out.println("Broken links: " + broken);
        } finally {
            driver.quit();
        }
    }

    private static int getStatus(String url) {
        try {
            HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
            connection.setRequestMethod("HEAD");
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);
            connection.connect();
            return connection.getResponseCode();
        } catch (Exception e) {
            return -1;
        }
    }
}

