public final class LocatorRepository {
    private static final Map<String, JsonNode> CACHE = new ConcurrentHashMap<>();
    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static By get(String page, String name) {
        JsonNode root = CACHE.computeIfAbsent(page, p -> {
            try (InputStream in = LocatorRepository.class
                    .getResourceAsStream("/locators/" + p + ".json")) {
                return MAPPER.readTree(in);
            } catch (IOException e) {
                throw new IllegalStateException("Cannot load locators for page: " + p, e);
            }
        });

        JsonNode node = root.get(name);
        if (node == null) {
            throw new IllegalArgumentException("Locator '" + name + "' not found in " + page + ".json");
        }

        String value = node.get("value").asText();
        switch (node.get("type").asText()) {
            case "id":    return By.id(value);
            case "css":   return By.cssSelector(value);
            case "xpath": return By.xpath(value);
            case "name":  return By.name(value);
            default: throw new IllegalArgumentException("Unknown locator type for " + name);
        }
    }
}

