public final class ExcelReader {

    // Value of a single cell, e.g. first row and first cell: getCell(path, "Sheet1", 0, 0)
    public static String getCell(String path, String sheetName, int rowIndex, int cellIndex) {
        try (FileInputStream in = new FileInputStream(path);
             Workbook workbook = new XSSFWorkbook(in)) {

            Sheet sheet = workbook.getSheet(sheetName);
            Cell cell = sheet.getRow(rowIndex).getCell(cellIndex);
            return new DataFormatter().formatCellValue(cell);
        } catch (IOException e) {
            throw new IllegalStateException("Cannot read Excel file: " + path, e);
        }
    }

    // Whole sheet for a DataProvider (row 0 is the header)
    public static Object[][] read(String path, String sheetName) {
        try (FileInputStream in = new FileInputStream(path);
             Workbook workbook = new XSSFWorkbook(in)) {

            Sheet sheet = workbook.getSheet(sheetName);
            DataFormatter formatter = new DataFormatter();
            int rows = sheet.getLastRowNum();
            int cols = sheet.getRow(0).getLastCellNum();

            Object[][] data = new Object[rows][cols];
            for (int r = 1; r <= rows; r++) {
                for (int c = 0; c < cols; c++) {
                    data[r - 1][c] = formatter.formatCellValue(sheet.getRow(r).getCell(c));
                }
            }
            return data;
        } catch (IOException e) {
            throw new IllegalStateException("Cannot read Excel file: " + path, e);
        }
    }
}

