public final class ScreenshotUtil {
    private static final AtomicInteger COUNTER = new AtomicInteger();
    private static final DateTimeFormatter FORMAT =
            DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss_SSS");      // immutable, thread-safe

    private ScreenshotUtil() { }

    // Stateless: the driver is a parameter, nothing is stored
    public static Path capture(WebDriver driver, String testName) throws IOException {
        String fileName = testName
                + "_T" + Thread.currentThread().getId()
                + "_" + LocalDateTime.now().format(FORMAT)
                + "_" + COUNTER.incrementAndGet() + ".png";

        Path target = Paths.get("screenshots", fileName);
        Files.createDirectories(target.getParent());

        File source = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
        return Files.copy(source.toPath(), target, StandardCopyOption.REPLACE_EXISTING);
    }
}

// Per-thread state lives in ThreadLocal
public final class TestContext {
    private static final ThreadLocal<Map<String, Object>> CONTEXT =
            ThreadLocal.withInitial(HashMap::new);

    public static void put(String key, Object value) { CONTEXT.get().put(key, value); }
    public static Object get(String key) { return CONTEXT.get().get(key); }
    public static void clear() { CONTEXT.remove(); }
}

public class ExtentListener implements ITestListener {
    private static ExtentReports extent;
    private static final ThreadLocal<ExtentTest> TEST = new ThreadLocal<>();

    @Override
    public void onStart(ITestContext context) {
        ExtentSparkReporter spark = new ExtentSparkReporter("reports/ExtentReport.html");
        spark.config().setReportName("Regression Report");
        spark.config().setDocumentTitle("Automation Results");
        spark.config().setTheme(Theme.DARK);

        extent = new ExtentReports();
        extent.attachReporter(spark);
        extent.setSystemInfo("Environment", System.getProperty("env", "qa"));
        extent.setSystemInfo("Browser", System.getProperty("browser", "chrome"));
    }

    @Override
    public void onTestStart(ITestResult result) {
        ExtentTest test = extent.createTest(result.getMethod().getMethodName());
        test.assignCategory(result.getMethod().getGroups());
        TEST.set(test);
    }

    @Override
    public void onTestSuccess(ITestResult result) {
        TEST.get().pass("Test passed");
    }

    @Override
    public void onTestFailure(ITestResult result) {
        TEST.get().fail(result.getThrowable());                 // embeds the error and stack trace
        String base64 = ((TakesScreenshot) DriverManager.getDriver())
                .getScreenshotAs(OutputType.BASE64);
        TEST.get().fail("Screenshot at failure",
                MediaEntityBuilder.createScreenCaptureFromBase64String(base64).build());
    }

    @Override
    public void onTestSkipped(ITestResult result) {
        TEST.get().skip(result.getThrowable());
    }

    @Override
    public void onFinish(ITestContext context) {
        extent.setSystemInfo("Total passed", String.valueOf(context.getPassedTests().size()));
        extent.flush();                                         // writes the HTML file
    }
}

public class ScreenshotListener implements ITestListener {

    @Override
    public void onTestFailure(ITestResult result) {
        WebDriver driver = DriverManager.getDriver();
        if (driver == null) {
            return;
        }

        // Embedded in the report as Base64
        String base64 = ((TakesScreenshot) driver).getScreenshotAs(OutputType.BASE64);
        ExtentManager.getTest().fail(result.getThrowable(),
                MediaEntityBuilder.createScreenCaptureFromBase64String(base64).build());

        // Also saved as a file with a unique name
        try {
            File source = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
            Path target = Paths.get("screenshots",
                    result.getName() + "_" + System.currentTimeMillis() + ".png");
            Files.createDirectories(target.getParent());
            Files.copy(source.toPath(), target);
        } catch (IOException e) {
            System.out.println("Could not save screenshot: " + e.getMessage());
        }
    }
}

