import com.deque.html.axecore.results.Results;
import com.deque.html.axecore.results.Rule;
import com.deque.html.axecore.selenium.AxeBuilder;

@Test
public void loginPageHasNoSeriousAccessibilityViolations() {
    driver.get("https://example.com/login");

    Results results = new AxeBuilder()
            .withTags(Arrays.asList("wcag2a", "wcag2aa"))
            .exclude(Collections.singletonList("#third-party-widget"))
            .analyze(driver);

    List<Rule> serious = results.getViolations().stream()
            .filter(rule -> "serious".equals(rule.getImpact()) || "critical".equals(rule.getImpact()))
            .collect(Collectors.toList());

    for (Rule rule : serious) {
        System.out.println(rule.getId() + " [" + rule.getImpact() + "] " + rule.getHelp()
                + " -> " + rule.getNodes().size() + " element(s)");
    }

    Assert.assertTrue(serious.isEmpty(), "Accessibility violations found: " + serious.size());
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        // In practice both files are streamed from disk (Excel exported or converted to CSV).
        // Small in-memory samples are used here so the program can be run directly.
        List<String> fileA = Arrays.asList("id,name,city", "1,Asha,Pune", "2,Ravi,Delhi", "3,Meena,Chennai");
        List<String> fileB = Arrays.asList("id,name,city", "1,Asha,Pune", "2,Ravi,Mumbai", "4,John,Goa");

        // Pass 1: key -> hash of the full row (a hash keeps memory small)
        Map<String, Integer> rowsA = new HashMap<>();
        for (int i = 1; i < fileA.size(); i++) {
            String line = fileA.get(i);
            rowsA.put(line.substring(0, line.indexOf(',')), line.hashCode());
        }

        // Pass 2: stream file B and compare by key
        int changed = 0, onlyInB = 0;
        for (int i = 1; i < fileB.size(); i++) {
            String line = fileB.get(i);
            String key = line.substring(0, line.indexOf(','));
            Integer hashA = rowsA.remove(key);

            if (hashA == null) {
                onlyInB++;
                System.out.println("ONLY IN B : " + line);
            } else if (hashA != line.hashCode()) {
                changed++;
                System.out.println("CHANGED   : key " + key + " -> " + line);
            }
        }

        // Whatever is left was never matched
        for (String key : new TreeSet<>(rowsA.keySet())) {
            System.out.println("ONLY IN A : key " + key);
        }

        System.out.println("Summary: changed=" + changed + ", onlyInA=" + rowsA.size() + ", onlyInB=" + onlyInB);
    }
}

